import sys
import getpass
import os

def compute_token(password):
    return hash(password)

def process_command(command, username):
    if command == "register":
        if os.path.exists("users.txt"):
            with open("users.txt", "r") as f:
                for line in f:
                    if line.startswith(f"{username}:"):
                        print("USER EXISTS")
                        sys.exit()
        password = getpass.getpass("Enter password: ")
        token = compute_token(password)
        with open("users.txt", "a") as f:
            f.write(f"{username}:{token}\n")
        print("REGISTERED")
    elif command == "login":
        password = getpass.getpass("Enter password: ")
        token = compute_token(password)
        found = False
        with open("users.txt", "r") as f:
            for line in f:
                if line.startswith(f"{username}:") and line.split(":", 1)[1] == token:
                    found = True
                    break
        if not found:
            print("LOGIN FAILED")
            sys.exit()
        print("LOGIN OK")
        data_file = f"{username}.data"
        if os.path.exists(data_file):
            with open(data_file, "r") as f:
                print(f.read())
        else:
            print("NO DATA")

if __name__ == "__main__":
    if len(sys.argv) != 3:
        print("Usage: python credman.py <command> <username>")
        sys.exit(1)
    process_command(sys.argv[1], sys.argv[2])

